### Fixing a bug

Fixes #49536
Fixes #49338

### What?
Starting on next.js 13.4.0, the `server.js` file created by the standalone output is incorrect because it does not wait until the Next handler is ready before node http server starts accepting requests. 

Initial requests will produce the following error:

```
TypeError: handler is not a function
at Server.<anonymous> (/tmp/app/server.js:29:11)
at Server.emit (node:events:513:28)
at parserOnIncoming (node:_http_server:998:12)
at HTTPParser.parserOnHeadersComplete (node:_http_common:128:17)
```

### Why?
The creation of the next server takes roughly 800ms on a basic hello world app which causes the initial requests to fail because the `handler` variable is not initialized. 

### Solution
This changes the order of code so that Next Server is initialized before the Node HTTP server and awaits until the promise is completed to kick off the HTTP server. 

### Alternative code

```js
let handler;

const server = http.createServer(async (req, res) => {
  try {
    await waitUntilHandlerIsReady(); // <---- wait here
    await handler(req, res);
  } catch (err) {
    console.error("Failed to call handler", err);
    res.statusCode = 500;
    res.end("Internal Server Error");
  }
});

async function waitUntilHandlerIsReady() {
  if (!handler) {
    await new Promise((resolve) => setTimeout(resolve, 200));
    await waitUntilHandlerIsReady();
  }
}
```

body:
Here is a server.js that works if it helps you: 

```js
const http = require("http");
const path = require("path");
const {
  createServerHandler,
} = require("next/dist/server/lib/render-server-standalone");

const dir = path.join(__dirname);

process.env.NODE_ENV = "production";
process.chdir(__dirname);

// Make sure commands gracefully respect termination signals (e.g. from Docker)
// Allow the graceful termination to be manually configurable
if (!process.env.NEXT_MANUAL_SIG_HANDLE) {
  process.on("SIGTERM", () => process.exit(0));
  process.on("SIGINT", () => process.exit(0));
}

const currentPort = parseInt(process.env.PORT, 10) || 3000;
const hostname = process.env.HOSTNAME || "localhost";
const keepAliveTimeout = parseInt(process.env.KEEP_ALIVE_TIMEOUT, 10);

// const nextConfig = {}; // ommitted for brevity

process.env.__NEXT_PRIVATE_STANDALONE_CONFIG = JSON.stringify(nextConfig);

createServerHandler({
  port: currentPort,
  hostname,
  dir,
  conf: nextConfig,
}).then((nextHandler) => {
  console.log("Creating http server");
  const server = http.createServer(async (req, res) => {
    try {
      console.log("Handling request");
      await nextHandler(req, res);
    } catch (err) {
      console.error("Failed to call handler", err);
      res.statusCode = 500;
      res.end("Internal Server Error");
    }
  });

  if (
    !Number.isNaN(keepAliveTimeout) &&
    Number.isFinite(keepAliveTimeout) &&
    keepAliveTimeout >= 0
  ) {
    console.log("Setting keep alive timeout", keepAliveTimeout);
    server.keepAliveTimeout = keepAliveTimeout;
  }

  server.listen(currentPort, async (err) => {
    if (err) {
      console.error("Failed to start server", err);
      process.exit(1);
    }

    console.log(
      "Listening on port",
      currentPort,
      "url: http://" + hostname + ":" + currentPort
    );
  });
}).catch(err => {
  console.error("Failed to create next server handler", err);
  process.exit(1);
});
```

You can copy it manually to the standalone directory to override the one Next.js generates after running a build: 
```
cp server.js .next/standalone/server.js
```
